package goast

func goAssessmentSupport() AssessmentSupport {
	return AssessmentSupport{
		Gates: []AssessmentGate{AssessmentGateArchitecture, AssessmentGateMaintainability, AssessmentGateSafety, AssessmentGateCoverage},
		Metrics: []MetricSupport{
			{ID: "score_model", Category: "reporting", Level: CapabilityBasic, Description: "Backend assessment scoring model identifier."},
			{ID: "gates", Category: "reporting", Level: CapabilityBasic, Description: "Assessment gates applied to the report."},
			{ID: "debt_marker_count", Category: "maintainability", Level: CapabilityBasic, Description: "Total TODO/FIXME/HACK/XXX/DEPRECATED markers in Go comments."},
			{ID: "debt_marker_counts", Category: "maintainability", Level: CapabilityBasic, Description: "Debt marker counts grouped by marker kind."},
			{ID: "max_cyclomatic_complexity", Category: "maintainability", Level: CapabilityBasic, Description: "Maximum AST-derived cyclomatic complexity across functions."},
			{ID: "max_nesting_depth", Category: "maintainability", Level: CapabilityBasic, Description: "Maximum nested control-flow depth across functions."},
			{ID: "max_function_loc", Category: "maintainability", Level: CapabilityBasic, Description: "Maximum non-comment lines in a function."},
			{ID: "large_function_count", Category: "maintainability", Level: CapabilityBasic, Description: "Functions above the configured non-comment LOC threshold."},
			{ID: "high_complexity_function_count", Category: "maintainability", Level: CapabilityBasic, Description: "Functions above the configured cyclomatic complexity threshold."},
			{ID: "ignored_error_count", Category: "safety", Level: CapabilityBasic, Description: "Assignments that discard call results with the blank identifier."},
			{ID: "unchecked_type_assertion_count", Category: "safety", Level: CapabilityBasic, Description: "Type assertions without comma-ok handling."},
			{ID: "defer_in_loop_count", Category: "safety", Level: CapabilityBasic, Description: "Defer statements inside loops."},
			{ID: "process_exit_count", Category: "safety", Level: CapabilityBasic, Description: "panic, log.Fatal, or os.Exit call sites."},
			{ID: "string_concat_in_loop_count", Category: "performance", Level: CapabilityBasic, Description: "String-like compound concatenation inside loops."},
		},
		Findings: []FindingSupport{
			{ID: "coverage_no_go_files", Category: "coverage", Level: CapabilityBasic, Description: "No Go files were indexed for the selected scope."},
			{ID: "architecture_high_fan_out", Category: "architecture", Level: CapabilityBasic, Description: "Unit import fan-out exceeds advisory pressure threshold."},
			{ID: "architecture_internal_import", Category: "architecture", Level: CapabilityBasic, Description: "Import crosses a Go internal package boundary."},
			{ID: "architecture_fan_out", Category: "architecture", Level: CapabilityBasic, Description: "Package fan-out exceeds configured architecture policy."},
			{ID: "architecture_<effect_name>", Category: "architecture", Level: CapabilityBasic, Description: "Warning-level custom architecture effect rule demoted to a finding."},
			{ID: "maintainability_high_pressure_unit", Category: "maintainability", Level: CapabilityBasic, Description: "Unit has high combined dependency, symbol, and implementation pressure."},
			{ID: "maintainability_debt_marker", Category: "maintainability", Level: CapabilityBasic, Description: "Go comment contains TODO/FIXME/HACK/XXX/DEPRECATED debt marker."},
			{ID: "quality_high_complexity_function", Category: "maintainability", Level: CapabilityBasic, Description: "Function exceeds cyclomatic complexity threshold."},
			{ID: "quality_deeply_nested_function", Category: "maintainability", Level: CapabilityBasic, Description: "Function exceeds control-flow nesting threshold."},
			{ID: "quality_large_function", Category: "maintainability", Level: CapabilityBasic, Description: "Function exceeds non-comment LOC threshold."},
			{ID: "quality_many_parameters", Category: "maintainability", Level: CapabilityBasic, Description: "Function exceeds parameter count threshold."},
			{ID: "quality_many_returns", Category: "maintainability", Level: CapabilityBasic, Description: "Function exceeds explicit return count threshold."},
			{ID: "quality_large_file", Category: "maintainability", Level: CapabilityBasic, Description: "File exceeds non-comment LOC threshold."},
			{ID: "quality_large_struct", Category: "maintainability", Level: CapabilityBasic, Description: "Struct exceeds field count threshold."},
			{ID: "quality_broad_interface", Category: "maintainability", Level: CapabilityBasic, Description: "Interface exceeds method count threshold."},
			{ID: "safety_incomplete_validation", Category: "safety", Level: CapabilityBasic, Description: "Validation completed with incomplete language facts."},
			{ID: "safety_ignored_error", Category: "safety", Level: CapabilityBasic, Description: "Assignment discards a call result with the blank identifier."},
			{ID: "safety_unchecked_type_assertion", Category: "safety", Level: CapabilityBasic, Description: "Type assertion does not use comma-ok form."},
			{ID: "safety_defer_in_loop", Category: "safety", Level: CapabilityBasic, Description: "Defer statement appears inside a loop."},
			{ID: "safety_process_exit", Category: "safety", Level: CapabilityBasic, Description: "Process-level exit or panic bypasses normal error handling."},
			{ID: "performance_string_concat_in_loop", Category: "performance", Level: CapabilityBasic, Description: "Compound string concatenation appears inside a loop."},
		},
		Violations: []ViolationSupport{
			{ID: "architecture_boundary_violation", Category: "architecture", Level: CapabilityBasic, Description: "Package dependency violates configured architecture layers."},
			{ID: "architecture_test_boundary_violation", Category: "architecture", Level: CapabilityBasic, Description: "Test dependency violates configured architecture layers."},
			{ID: "architecture_denied_import", Category: "architecture", Level: CapabilityBasic, Description: "Import is denied by explicit architecture import rules."},
			{ID: "architecture_test_boundary_import", Category: "architecture", Level: CapabilityBasic, Description: "Test import is denied by explicit architecture import rules."},
			{ID: "architecture_unknown_package", Category: "architecture", Level: CapabilityBasic, Description: "Package in module does not match a configured architecture layer."},
			{ID: "architecture_effect_import", Category: "architecture", Level: CapabilityBasic, Description: "Import violates a configured side-effect rule."},
			{ID: "architecture_effect_call", Category: "architecture", Level: CapabilityBasic, Description: "Call violates a configured side-effect rule."},
			{ID: "architecture_<effect_name>", Category: "architecture", Level: CapabilityBasic, Description: "Custom architecture effect rule kind derived from the configured effect name."},
			{ID: "safety_validation_diagnostic", Category: "safety", Level: CapabilityBasic, Description: "Go parse or typecheck validation diagnostic."},
		},
	}
}
